Aquí está un ejemplo de un programa en C++ que lee un archivo de texto línea por línea y cuenta el número de apariciones de una palabra específica en el archivo:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int contar_palabras(string palabra, string archivo) {
    int contador = 0;

    // Abrir el archivo
    ifstream archivo_texto(archivo);

    // Comprobar si se abrió correctamente
    if (!archivo_texto.is_open()) {
        cout << "No se pudo abrir el archivo " << archivo << endl;
