    }

    // Leer línea por línea
    string linea;
    while (getline(archivo_texto, linea)) {
        // Convertir la línea a minúsculas para hacer una comparación de caso insensible
        transform(linea.begin(), linea.end(), linea.begin(), ::tolower);

        // Comprobar si la línea contiene la palabra
        if (linea.find(palabra) != string::npos) {
            // Aumentar el contador si la línea contiene la palabra
            contador++;
        }
    }

    // Cerrar el archivo
    archivo_texto.close();

    return contador;
}

int main() {
    string palabra, archivo;
    cout << "Palabra a buscar: ";
    cin >> palabra;
    cout << "Nombre del archivo de texto: ";
    cin >> archivo;

    int contador = contar_palabras(palabra, archivo);

    if (contador < 0) {
        return 1;
    }

